import{_ as a,o as s,c as t,a2 as r}from"./chunks/framework.CQxpk36T.js";const m=JSON.parse('{"title":"Le rendu 3D","description":"","frontmatter":{},"headers":[],"relativePath":"developpement/rendu.md","filePath":"developpement/rendu.md","lastUpdated":1793572677000}'),n={name:"developpement/rendu.md"};function l(i,e,u,o,d,c){return s(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="le-rendu-3d" tabindex="-1">Le rendu 3D <a class="header-anchor" href="#le-rendu-3d" aria-label="Permalink to &quot;Le rendu 3D&quot;">​</a></h1><p>L&#39;objectif : une maquette douillette, fluide sur un téléphone, qui ne vide pas sa batterie.</p><h2 id="materiaux" tabindex="-1">Matériaux <a class="header-anchor" href="#materiaux" aria-label="Permalink to &quot;Matériaux&quot;">​</a></h2><p>Les matériaux sont des <code>MeshStandardMaterial</code> de three.js, dans lesquels des motifs sont greffés en GLSL (<code>src/scene/shaders.ts</code>) : crépi, colombages, tuiles, pavés, herbe, bois. Des <strong>uniformes partagés</strong> portent l&#39;heure, le vent, la pluie et la neige ; un seul endroit suffit pour que tout se mouille ou blanchisse.</p><h2 id="peu-de-commandes-de-dessin" tabindex="-1">Peu de commandes de dessin <a class="header-anchor" href="#peu-de-commandes-de-dessin" aria-label="Permalink to &quot;Peu de commandes de dessin&quot;">​</a></h2><ul><li>Une commande de dessin <strong>par matériau et par bâtiment</strong> : géométries fusionnées.</li><li>Les détails répétés (fenêtres, volets, bûches, modules solaires, buissons) en <code>InstancedMesh</code>.</li></ul><h2 id="eclairage-precalcule" tabindex="-1">Éclairage précalculé <a class="header-anchor" href="#eclairage-precalcule" aria-label="Permalink to &quot;Éclairage précalculé&quot;">​</a></h2><p>L&#39;occlusion ambiante et la lumière des lanternes sont calculées une fois, par rayons sur un BVH (<a href="https://github.com/gkjohnson/three-mesh-bvh" target="_blank" rel="noreferrer">three-mesh-bvh</a>) dans un Web Worker, et stockées <strong>par sommet</strong>. Le résultat est gardé en IndexedDB d&#39;une visite à l&#39;autre. Les lanternes n&#39;ont pas de vraie lumière ponctuelle : elle coûterait sur chaque pixel et forcerait la recompilation des shaders au passage jour / nuit ; leur lumière précalculée est simplement dosée.</p><h2 id="rendu-a-la-demande" tabindex="-1">Rendu à la demande <a class="header-anchor" href="#rendu-a-la-demande" aria-label="Permalink to &quot;Rendu à la demande&quot;">​</a></h2><ul><li>L&#39;image ne se recalcule <strong>que si quelque chose bouge</strong>.</li><li>L&#39;ambiance (vent, nuages, animaux) tourne à cadence réduite.</li><li>La carte d&#39;ombres n&#39;est refaite que quand le soleil ou une porte bouge.</li></ul><h2 id="qualite-adaptee" tabindex="-1">Qualité adaptée <a class="header-anchor" href="#qualite-adaptee" aria-label="Permalink to &quot;Qualité adaptée&quot;">​</a></h2><p>Un budget de pixels et la mesure du temps GPU règlent la définition. Le post-traitement (halo, contour de sélection, flou de maquette) n&#39;est actif qu&#39;en qualité haute.</p><h2 id="vue-en-coupe" tabindex="-1">Vue en coupe <a class="header-anchor" href="#vue-en-coupe" aria-label="Permalink to &quot;Vue en coupe&quot;">​</a></h2><p>Une <strong>boîte de coupe</strong> (plans de découpe posés une fois sur tous les matériaux) masque ce qui dépasse dans l&#39;emprise du bâtiment ; l&#39;étage est généré depuis <code>plans.ts</code>. Un filtre des événements de la scène écarte des clics ce que la coupe masque : toucher le sol d&#39;une pièce atteint bien la pièce, pas le plafond invisible au-dessus.</p><ul><li><strong>Les voisins</strong> sont tranchés à la même hauteur, au lieu d&#39;être tramés : le test d&#39;estompage écarte simplement ce qui dépasse la hauteur de coupe dans leur emprise.</li><li><strong>La tranche des murs</strong> (leurs faces arrière) est peinte en aplat uni, sans lumière ni ombre.</li><li><strong>Les pièces allumées</strong> reçoivent la lumière d&#39;un plafonnier (<code>src/scene/roomLamps.ts</code>) : pas de vraie lumière three.js, qui recompilerait tous les matériaux, mais une lumière chaude calculée dans les matériaux, bornée à la pièce. Le reste de l&#39;intérieur est à l&#39;ombre, comme un intérieur.</li></ul><h2 id="estompage" tabindex="-1">Estompage <a class="header-anchor" href="#estompage" aria-label="Permalink to &quot;Estompage&quot;">​</a></h2><p>Quand un bâtiment est sélectionné, les autres passent en <strong>tramage</strong> : une partie des pixels est écartée selon un motif régulier, sans tri de transparence. Le test « dans l&#39;emprise d&#39;un autre bâtiment » est greffé une fois dans tous les matériaux ; les clics traversent ce qui est estompé quand le bâtiment sélectionné est derrière.</p><h2 id="toucher-ou-glisser" tabindex="-1">Toucher ou glisser <a class="header-anchor" href="#toucher-ou-glisser" aria-label="Permalink to &quot;Toucher ou glisser&quot;">​</a></h2><p>Un toucher qui se déplace de plus de 12 pixels (<code>TAP_SLOP</code>, <code>src/scene/tap.ts</code>) est un glissé : il fait tourner la caméra sans actionner ce qui est dessous.</p>',19)])])}const h=a(n,[["render",l]]);export{m as __pageData,h as default};
